fn add_contact(book: &mut Map[Str, Int], name: Str, number: Int) -> Unit {
  book.insert(name, number);
}

fn delete_contact(book: &mut Map[Str, Int], name: Str) -> Bool {
  if book.contains(&name) {
    book.remove(&name);
    return true;
  }
  return false;
}

fn contact_count(book: &Map[Str, Int]) -> Int {
  return book.len();
}

fn main() -> Int {
  var book = Map[Str, Int]();
  add_contact(&mut book, "Alice", 12345);
  add_contact(&mut book, "Bob", 23456);
  add_contact(&mut book, "Carol", 34567);
  delete_contact(&mut book, "Bob");
  return contact_count(&book);
}
